import json
from pathlib import Path
from prepare import O,MODELS,js
N={'unet':'U-Net','deeplab':'DeepLabV3+','segformer':'SegFormer-B0'};C={2:'新生根',1:'持续根',3:'生长根（根尖延伸）'}
def main():
 s=json.loads((O/'metrics_summary.json').read_text());prep=json.loads((O/'data/preparation.json').read_text());rows=s['temporal_classes'];lines=['# 上传17 · 三时序分支加入GAT：训练与结果','', '本轮已完成三组GAT与三组无GAT（MLP）对照，各100轮真实优化。原标注、旧时序头、旧二值分割与旧结果保留；新结果单独保存。本次结果不支持三模型、三类别均得到提升，也不支持自动替换人工编号。','', '## 三类时序结果','', '下表为相同26条留出人工根号家族范围内的逐类Dice。Before是旧V44输出在这套新分组上的重新统计，不是复制旧V44汇总表。MLP与GAT使用完全相同的新标签、输入特征、分组、训练轮次和检查点选择规则。','', '| 类别 | 模型 | Before | 新MLP对照 | 新GAT | GAT−Before |','|---|---|---:|---:|---:|---:|']
 for k in [2,1,3]:
  for m in MODELS:
   v={r['variant']:r['Dice'] for r in rows if r['model']==m and r['class_code']==k};lines.append(f"| {C[k]} | {N[m]} | {v['archived']:.4f} | {v['mlp']:.4f} | {v['gat']:.4f} | {v['gat']-v['archived']:+.4f} |")
 lines+=['','持续根三模型均略升；新生根仅U-Net提高；生长根仅SegFormer-B0提高。无GAT对照在部分指标上更好，完整Precision、Recall、Dice、IoU及混淆计数均保存在CSV。','', '## 编号学习与完整跟踪','', '根号是任意命名，网络学习的是同根、母侧根和不同根的关系，不将0001等数字当作可泛化类别。142条已确认人工根号监督训练与评估；12条未确认的assistant补标不参与监督。模型输出先是匿名P-xxxx轨迹，再用每条根首次可见期的名称锚定显示。首次期只是名称锚点，不计入后续编号准确率。四期后验关联为离线跟踪，不是只看当前一张图的独立编号分类。','', '| 模型 | 对照/方法 | 同根候选配对F1 | 后续根期名称一致率 | 像素分组ARI |','|---|---|---:|---:|---:|']
 for r in s['identity']:lines.append(f"| {N[r['model']]} | {r['variant'].upper()} | {r['same_root_F1']:.4f} | {r['heldout_post_seed_name_accuracy']:.4f} | {r['heldout_pixel_adjusted_Rand']:.4f} |")
 lines+=['','后续名称一致率使用69个“根×后续时期”案例，不能与配对F1等同。GAT的部分关联排序AP和像素分组ARI提高，但当前配对阈值下F1和完整编号恢复仍不足。预测中的错误归并、碎片与未命名轨迹均保留，未回写人工标注。','', '## 数据、结构与评估边界','', 'B3的四期全部属于同一个外层开发位置。下文train/validation/test仅表示开发池内的根家族监督遮蔽，不是独立位置或微根管的数据分区；本轮没有外部验证/测试位置。','', f"上传原文件SHA256：`{prep['source_SHA256']}`。原始JSON保存在data/source_progress_17.json，人工142条编号及四期状态另见Human_root_IDs_four_periods.csv。",'', '同一根及其母根家族四期保持同一分组：85条训练、31条验证、26条测试，共54个母根家族。142是人工已确认身份数，7539是计算图节点数，79888是几何候选对数，不能视作独立图像或真实根条数。','', '三个分支复用V44/V43的旧时序概率与原生根轮廓。新增模块使用43维RGB、跨期RGB差异、几何、原模型概率等特征；GAT为2层4头、96维结构注意力，接时序残差与3类关联头。MLP对照共享43维输入、相同监督和关联输出头；参数量不同，具体数量保存在各config.json。没有把人工根号、母根名称、图上编号颜色或人工连接关系作为数值输入。候选图只由几何生成，未确认轨迹可作为无标签上下文。','', '这是同一视野中的传导式特征图：训练时可见无标签的全图几何和原模型特征，仅训练家族的监督进入损失。不是跨微根管独立测试，也不是从原始RGB重新训练完整CNN主干的实验。人工根段的几何作为固定条件，不能把本编号结果说成端到端的独立实例分割。','', '时序像素参考仍保留原文件的U-Net辅助修订来源；根号经用户确认不等于每个时序像素已成为独立人工真值。本轮指标是该参考下的内部一致性。','', '时序性能在留出人工根像素及其6像素背景邻域统计，忽略其他未评价根；包括漏根与背景误报。三分支原有根/背景支持严格冻结，所以图分支无法补回旧二值模型漏掉的根像素。生长/延伸段仍是主要短板；是否主要来自类不平衡、图传播或特征不足，尚未确定。','', '新增网络随机初始化，时序残差初始为零；旧影像分支保留。每轮为一次全图更新，每个新模块100轮，记录实际训练目标、验证类别Dice与配对F1。AdamW .002到.00002余弦退火；损失为加权像素CE、soft Dice、关联CE和小残差正则。权重以0.75验证类别宏Dice+0.25验证同根F1选择；关联阈值只由验证集选择。','', '每轮原子保存resume.pt（网络、优化器、学习率、RNG和历史）、最佳权重与CSV日志。训练、数据准备、评估和绘图分阶段保存，已完成训练不会重复启动。','', '## 文件','', '- 新生根、持续根、生长根分别有Before/+GAT对比TIF。共同展示窗口沿用上一版[1440,120,1824,504]，仅定性展示；参考与三个模型使用同一位置。','- Table_Three_classes_before_after_GAT.tif与Temporal_class_metrics_before_after.csv：逐类完整指标。','- Fig_GAT_MLP_temporal_ablation.tif：旧分支、MLP、GAT三方对照，保留下降结果。','- Fig_Root_ID_comparison.tif、Root_ID_comparison.html、Root_ID_comparison_all_models.csv：人工编号/预测轨迹/锚定显示编号对比。HTML下载后浏览器打开，原图首次需联网；P编号不等于确认新生根。','- Fig_Root_ID_tracking_ablation.tif与Root_ID_tracking_metrics.csv：配对与完整跟踪指标分开。','- Fig_GAT_training_monitoring.tif及每个新模块history.csv：真实100轮新增分支训练过程。','- data/下特征、图、目标和原标注，source/下可复现代码；各模型目录保存initial.pt、best.pt、resume.pt与config/completion。','', '## 核验','', 'learning_verification.json将所有根内部ID与显示名称替换后重建输入，核对几何边、监督分组和三模型输入均不变；另验证GAT节点置换等变与AUC/AP的并列分数处理。final_verification.json核对100轮记录、实际权重变化、分组隔离、输入摘要和二值轮廓。viewer_verification.json绑定最终HTML，检查四期切换、搜索、侧根家族、同步缩放/平移和根线点击。','']
 text='\n'.join(lines);(O/'RESULTS.md').write_text(text);(O/'README.md').write_text(text);print('REPORT_WRITTEN',flush=True)
if __name__=='__main__':main()
